import { render, screen } from '@testing-library/react';
import { describe, expect, it, vi } from 'vitest';
import Atividade from './Atividade.jsx';

const SALAS = [
  { id: 'auditorio', nome: 'Auditório Central', capacidade: 200 },
  { id: 'lab-3', nome: 'Laboratório 3', capacidade: 20 },
];

const minicurso = {
  id: 'atv_minicurso02',
  titulo: 'Flutter do zero',
  tipo: 'minicurso',
  salaId: 'lab-3',
  vagas: 20,
  encontros: [
    { id: 'enc_2', inicio: '2026-10-20T09:00:00-03:00', fim: '2026-10-20T12:00:00-03:00' },
    { id: 'enc_1', inicio: '2026-10-19T19:00:00-03:00', fim: '2026-10-19T21:00:00-03:00' },
  ],
  cargaHorariaMinutos: 300,
  situacao: 'em_andamento',
  ocupadas: 8,
  vagasRestantes: 12,
  emEspera: 0,
};

function criarApiFalsa({ atividade = minicurso, erro } = {}) {
  return {
    listarSalas: vi.fn(async () => SALAS),
    obterAtividade: vi.fn(() =>
      erro ? Promise.reject(erro) : Promise.resolve(atividade),
    ),
  };
}

describe('Atividade', () => {
  it('mostra os dados da atividade com os encontros ordenados pelo início', async () => {
    const api = criarApiFalsa();
    render(<Atividade api={api} id="atv_minicurso02" />);

    expect(await screen.findByText('Flutter do zero')).toBeInTheDocument();
    expect(screen.getByText('Minicurso')).toBeInTheDocument();
    expect(screen.getByText('Laboratório 3')).toBeInTheDocument();
    expect(screen.getByText(/12 de 20 vagas/)).toBeInTheDocument();
    expect(screen.getByText(/8 ocupadas/)).toBeInTheDocument();
    expect(screen.getByText('5h')).toBeInTheDocument();
    expect(screen.getByText('Em andamento')).toBeInTheDocument();
    expect(api.obterAtividade).toHaveBeenCalledWith('atv_minicurso02');

    const encontros = screen.getAllByRole('listitem');
    expect(encontros[0]).toHaveTextContent('19:00');
    expect(encontros[1]).toHaveTextContent('09:00');
  });
});

import { useEffect, useMemo, useState } from 'react';

const ROTULOS_SITUACAO = {
  prevista: 'Prevista',
  em_andamento: 'Em andamento',
  encerrada: 'Encerrada',
  cancelada: 'Cancelada',
};

function rotuloTipo(tipo) {
  return tipo === 'minicurso' ? 'Minicurso' : 'Palestra';
}

function rotuloSituacao(situacao) {
  return ROTULOS_SITUACAO[situacao] || situacao;
}

function horarioEmBrasilia(iso) {
  return new Date(iso)
    .toLocaleTimeString('pt-BR', {
      timeZone: 'America/Sao_Paulo',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    })
    .replace('24:', '00:');
}

function formatarCargaHoraria(minutos) {
  const horas = Math.floor(minutos / 60);
  const resto = minutos % 60;
  if (horas === 0) return `${resto} min`;
  if (resto === 0) return `${horas}h`;
  return `${horas}h${resto}`;
}

export default function Atividade({ api, id }) {
  const [atividade, setAtividade] = useState(null);
  const [erro, setErro] = useState(null);
  const [salas, setSalas] = useState([]);

  useEffect(() => {
    api.listarSalas().then(setSalas).catch(() => {});
  }, [api]);

  useEffect(() => {
    setErro(null);
    setAtividade(null);
    api
      .obterAtividade(id)
      .then(setAtividade)
      .catch((erroDaApi) => setErro(erroDaApi));
  }, [api, id]);

  const nomeDaSala = useMemo(() => {
    const mapa = {};
    for (const sala of salas) {
      mapa[sala.id] = sala.nome;
    }
    return (salaId) => mapa[salaId] || salaId;
  }, [salas]);

  const encontros = useMemo(
    () =>
      atividade
        ? [...atividade.encontros].sort((a, b) => new Date(a.inicio) - new Date(b.inicio))
        : [],
    [atividade],
  );

  return (
    <section aria-label="Detalhes da atividade">
      {erro && (
        <p role="alert">
          {erro.erro}: {erro.mensagem || erro.message}
        </p>
      )}

      {atividade && !erro && (
        <article aria-label={atividade.titulo}>
          <h2>{atividade.titulo}</h2>
          <p>{rotuloTipo(atividade.tipo)}</p>
          <p>{nomeDaSala(atividade.salaId)}</p>
          <p>
            {atividade.vagasRestantes} de {atividade.vagas} vagas · {atividade.ocupadas}{' '}
            ocupadas
          </p>
          <p>Carga horária: {formatarCargaHoraria(atividade.cargaHorariaMinutos)}</p>
          <p>Situação: {rotuloSituacao(atividade.situacao)}</p>
          <ul aria-label="Encontros">
            {encontros.map((encontro) => (
              <li key={encontro.id}>
                {horarioEmBrasilia(encontro.inicio)}–{horarioEmBrasilia(encontro.fim)}
              </li>
            ))}
          </ul>
        </article>
      )}
    </section>
  );
}

